  p.removeAllEffects();p.getAbilities().invulnerable=true;baubles.setItem(1,item("emt:one_ring"));((IBauble)baubles.getItem(1).getItem()).onWornTick(baubles.getItem(1),p);baubles.removeItem(1,1);check("ring preserves pre-existing invulnerability",p.getAbilities().invulnerable,"prior state");p.getAbilities().invulnerable=false;p.removeAllEffects();baubles.setItem(1,item("emt:one_ring"));baubles.setItem(2,item("emt:one_ring"));((IBauble)baubles.getItem(1).getItem()).onWornTick(baubles.getItem(1),p);baubles.removeItem(1,1);check("removing one of two rings keeps active ring protection",p.isInvisible()&&p.getAbilities().invulnerable,"other ring");baubles.removeItem(2,1);check("removing last ring restores saved survival state",!p.isInvisible()&&!p.getAbilities().invulnerable,"last ring");
